refer\u00eancia.","alternatives":[{"id":"01a21904-ae08-713e-b319-0da7fa96c8d6","description":"O dobro da velocidade do som","correct_answer":true},{"id":"01a21904-ae08-71a5-8d90-f9b02f81cb5d","description":"O dobro da velocidade da luz","correct_answer":false},{"id":"01a21904-ae08-753d-8cc0-0fb294e2e6db","description":"200 milhas por hora","correct_answer":false},{"id":"01a21904-ae08-7098-b0a1-60f95eb945eb","description":"2 milhas por segundo","correct_answer":false}]},{"id":"01a21904-ae08-7b20-ae14-1a76e72120f0","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Qual dessas teorias cient\u00edficas representou um avan\u00e7o em rela\u00e7\u00e3o \u00e0 teoria da mec\u00e2nica de Isaac Newton?","difficulty":2,"explanation":"A relatividade geral amplia a gravidade newtoniana e prev\u00ea que objetos massivos desviam a luz, um efeito confirmado por observa\u00e7\u00f5es pr\u00f3ximas ao Sol.","alternatives":[{"id":"01a21904-ae08-7ce1-8760-e34bb00ed08d","description":"Relatividade geral","correct_answer":true},{"id":"01a21904-ae08-7397-acfd-21f62fbf1050","description":"Lamarckismo","correct_answer":false},{"id":"01a21904-ae08-7401-9dad-bbdaf641629c","description":"Equa\u00e7\u00f5es de Maxwell","correct_answer":false},{"id":"01a21904-ae08-78b5-8ebb-bf1b2f290fb8","description":"Lei de Snell","correct_answer":false}]},{"id":"01a21904-ae08-7bc0-9b52-570c6c7503ed","category":"01a2135e-b9ba-7fbd-8736-4a658c8d2151","question":"Quantas v\u00e9rtebras cervicais uma girafa tem?","difficulty":2,"explanation":"Sete tamb\u00e9m \u00e9 o n\u00famero normal de v\u00e9rtebras cervicais nos seres humanos; as v\u00e9rtebras das girafas s\u00e3o simplesmente muito mais longas.","alternatives":[{"id":"01a21904-ae08-7c85-8ea2-46b7e80f5947","description":"Sete","correct_answer":true},{"id":"01a21904-ae08-77f7-8aba-ea96f473e6eb","description":"Quatorze","correct_answer":false},{"id":"01a21904-ae08-7ab9-8fad-4ecee2729745","description":"Nove","correct_answer":false},{"id":"01a2190